from __future__ import annotations

import sqlite3
from typing import Optional

from fastapi import APIRouter, Depends, Query, status
from pydantic import BaseModel, Field

from app.config import Settings, get_settings
from app.db import get_db, utc_now
from app.errors import not_found
from app.pagination import PageParams, page_params, paginate
from app.security import CurrentUser, get_current_user

router = APIRouter(prefix="/api/todos", tags=["todos"])

class TodoCreate(BaseModel):
    title: str = Field(min_length=1, max_length=200)

class TodoUpdate(BaseModel):
    title: Optional[str] = Field(default=None, min_length=1, max_length=200)
    done: Optional[bool] = None

class TodoResponse(BaseModel):
    id: int
    title: str
    done: bool
    created_at: str
    updated_at: str

class TodoListResponse(BaseModel):
    items: list[TodoResponse]
    total: int
    limit: int
    offset: int

def _todo_to_response(row: sqlite3.Row) -> TodoResponse:
    return TodoResponse(
        id=row["id"],
        title=row["title"],
        done=bool(row["done"]),
        created_at=row["created_at"],
        updated_at=row["updated_at"],
    )

@router.get("", response_model=TodoListResponse)
def list_todos(
    done: Optional[bool] = Query(default=None),
    page: PageParams = Depends(page_params),
    current_user: CurrentUser = Depends(get_current_user),
    conn: sqlite3.Connection = Depends(get_db),
) -> TodoListResponse:
    where = ["user_id = ?"]
    params: list = [current_user.id]
    if done is not None:
        where.append("done = ?")
        params.append(1 if done else 0)
    where_sql = " AND ".join(where)

    total_row = conn.execute(f"SELECT COUNT(*) FROM todos WHERE {where_sql}", params).fetchone()
    total = total_row[0] if total_row else 0

    rows = conn.execute(
        f"SELECT * FROM todos WHERE {where_sql} ORDER BY created_at DESC LIMIT ? OFFSET ?",
        params + [page.limit, page.offset],
    ).fetchall()

    items = [_todo_to_response(row) for row in rows]
    return paginate(items, total, page)

@router.post("", response_model=TodoResponse, status_code=status.HTTP_201_CREATED)
def create_todo(
    data: TodoCreate,
    current_user: CurrentUser = Depends(get_current_user),
    conn: sqlite3.Connection = Depends(get_db),
) -> TodoResponse:
    now = utc_now()
    title = data.title.strip()
    cur = conn.execute(
        "INSERT INTO todos (user_id, title, done, created_at, updated_at) VALUES (?, ?, 0, ?, ?)",
        (current_user.id, title, now, now),
    )
    conn.commit()
    row = conn.execute("SELECT * FROM todos WHERE id = ?", (cur.lastrowid,)).fetchone()
    return _todo_to_response(row)

@router.get("/{todo_id}", response_model=TodoResponse)
def get_todo(
    todo_id: int,
    current_user: CurrentUser = Depends(get_current_user),
    conn: sqlite3.Connection = Depends(get_db),
) -> TodoResponse:
    row = conn.execute("SELECT * FROM todos WHERE id = ? AND user_id = ?", (todo_id, current_user.id)).fetchone()
    if not row:
        raise not_found("todo_not_found", "Todo not found")
    return _todo_to_response(row)

@router.patch("/{todo_id}", response_model=TodoResponse)
def update_todo(
    todo_id: int,
    data: TodoUpdate,
    current_user: CurrentUser = Depends(get_current_user),
    conn: sqlite3.Connection = Depends(get_db),
) -> TodoResponse:
    row = conn.execute("SELECT * FROM todos WHERE id = ? AND user_id = ?", (todo_id, current_user.id)).fetchone()
    if not row:
        raise not_found("todo_not_found", "Todo not found")

    updates = []
    params = []
    if data.title is not None:
        updates.append("title = ?")
        params.append(data.title.strip())
    if data.done is not None:
        updates.append("done = ?")
        params.append(1 if data.done else 0)
    if not updates:
        return _todo_to_response(row)

    updates.append("updated_at = ?")
    params.append(utc_now())
    params.extend([todo_id, current_user.id])

    conn.execute(f"UPDATE todos SET {', '.join(updates)} WHERE id = ? AND user_id = ?", params)
    conn.commit()
    row = conn.execute("SELECT * FROM todos WHERE id = ? AND user_id = ?", (todo_id, current_user.id)).fetchone()
    return _todo_to_response(row)

@router.delete("/{todo_id}", status_code=status.HTTP_204_NO_CONTENT)
def delete_todo(
    todo_id: int,
    current_user: CurrentUser = Depends(get_current_user),
    conn: sqlite3.Connection = Depends(get_db),
) -> None:
    cur = conn.execute("DELETE FROM todos WHERE id = ? AND user_id = ?", (todo_id, current_user.id))
    conn.commit()
    if cur.rowcount == 0:
        raise not_found("todo_not_found", "Todo not found")
